import sys


class Student:
    def __init__(self, name, rollNumber, marks):
        self.name = name
        self.rollNumber = rollNumber
        self.marks = marks

    def get_grade(self):
        if self.marks >= 90:
            return "A"
        elif self.marks >= 75:
            return "B"
        elif self.marks >= 50:
            return "C"
        else:
            return "Fail"


class GraduateStudent(Student):
    def __init__(self, name, rollNumber, marks, thesisTitle):
        super().__init__(name, rollNumber, marks)
        self.thesisTitle = thesisTitle

    def display(self):
        print(self.get_grade())
        print(self.thesisTitle)


def main():
    data = sys.stdin.read().splitlines()
    if len(data) < 4:
        return
    name = data[0]
    rollNumber = int(data[1].strip())
    marks = int(data[2].strip())
    thesisTitle = data[3]

    student = GraduateStudent(name, rollNumber, marks, thesisTitle)
    student.display()


if __name__ == "__main__":
    main()
